style.css:
@-moz-document regexp(".*") {
/* Apply to all websites for demonstration, adjust as needed */

    /* General dark background for the page */
    body {
        background-color: #121212 !important; /* Very dark grey, like the night sky */
        color: #E0E0E0 !important; /* Light grey for text, mimicking illuminated windows */
        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
    }

    /* Styling for headings to stand out */
    h1, h2, h3, h4, h5, h6 {
        color: #FFFFFF !important; /* Pure white for strong contrast */
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Subtle shadow like city lights */
    }

    /* Links for a touch of accent, like glowing signs */
    a {
        color: #7AAFFF !important; /* A cool blue for a modern, electric feel */
        text-decoration: none !important;
    }

    a:hover {
        color: #A3D2FF !important; /* Lighter blue on hover */
        text-decoration: underline !important;
    }

    /* Background for content areas or cards, slightly lighter than body */
    .content-area, .card {
        background-color: #282828 !important; /* Slightly lighter grey for content blocks */
        border: 1px solid #444444 !important; /* Subtle border for definition */
        border-radius: 5px !important;
        padding: 15px !important;
        box-shadow: 0px 0px 5px rgba(0, 0, 0, 0.3); /* Soft shadow for depth */
    }

    /* Buttons with a sleek, minimalist look */
    button, input[type="submit"], .btn {
        background-color: #3A3A3A !important; /* Dark button background */
        color: #FFFFFF !important;
        border: 1px solid #555555 !important;
        border-radius: 3px !important;
        padding: 8px 15px !important;
        cursor: pointer !important;
        transition: background-color 0.3s ease !important;
    }

    button:hover, input[type="submit"]:hover, .btn:hover {
        background-color: #4A4A4A !important; /* Slightly lighter on hover */
    }
}
